function open_news(_this, e){
	e.preventDefault();
	var news_id = $(_this).attr('news_id');
	$.post('index.php?mod='+MOD+'&act=open_news', {
		'news_id' : news_id
	}, function(html){
		var __w = $(window).width();
		$Core.popup.openfull(__w*1/3,html,'open_news');
	});
	return false;
}
function load_post_more(_this, e){
	e.preventDefault();
	var cat_id = $(_this).attr('cat_id'),
		total_record = $(_this).attr('total_record'),
		total_loaded = $(_this).attr('total_loaded'),
		order_no = $('.awe__post-item:last').attr('order_no');
	$.post('index.php?mod=post&act=load_post_more', {
		'cat_id' : cat_id,
		'total_record' : total_record,
		'total_loaded' : total_loaded,
		'order_no' : order_no
	}, function(respJson){
		$('.awe__post-item:last').after(respJson.html);
		$(_this).attr('total_loaded', respJson.total_loaded);
		if(parseInt(respJson.total_loaded, 10) >= total_record){
			$(_this).parent().remove();
		}
	}, 'json');
	return false;
}
$(function(){
	$_document.on('click', '.awe__post-like-action', function(e){
		e.preventDefault();
		var _this = $(this),
			post_id = _this.attr('post_id');
		$.post('index.php?mod=post&act=like', {
			'post_id' : post_id
		}, function(html){
			if(html.indexOf('_invalid') >= 0){
				
			} else {
				_this.replaceWith(html);
			}
		});
		return false;
	});
	
})